def caesarCipher(string, shift):
    result = ""
    for char in string:
        char_code = ord(char)+shift
        if char_code < ord('A'):
            result += chr(ord('Z')- abs(char_code) + 1)
        elif char_code > ord('Z'):
            result += chr(ord('A') + abs(char_code) - 1)
        else:
            result += chr(char_code)
    return result
