def longest_common_substring(s1, s2):
    n1, n2 = len(s1), len(s2)
    lcs_matrix = [[0]*(n2 + 1) for _ in range(n1 + 1)]

    longest_length, end_of_longest = 0, 0
    for i in range(1, n1 + 1):
        for j in range(1, n2 + 1):
            if s1[i-1] == s2[j-1]:
                lcs_matrix[i][j] = lcs_matrix[i-1][j-1] + 1

                if lcs_matrix[i][j] > longest_length:
                    longest_length = lcs_matrix[i][j]
                    end_of_longest = i
            else:
                lcs_matrix[i][j] = 0

    return s1[end_of_longest-longest_length:end_of_longest]
