def quick_sort(A):

  if len(A) <= 1:
    return A


  pivot_idx = len(A) // 2
  pivot_val = A[pivot_idx]


  left = []
  right = []


  for i in range(len(A)):
    if i == pivot_idx:
      continue
    elif A[i] < pivot_val:
      left.append(A[i])
    else:
      right.append(A[i])


  return quick_sort(left) + [pivot_val] + quick_sort(right)
